  1	/* ============================================================
  2	   views/config.js — Configuration view
  3	   Section 4d of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	/* ── Module-level state ──────────────────────────────────── */
  8	
  9	var configActiveTab = 'general';
 10	
 11	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes */
 12	var configDirty = {
 13	  general: false,
 14	  personaModels: false,
 15	  modelRegistry: false
 16	};
 17	
 18	/* ── Entry point ─────────────────────────────────────────── */
 19	
 20	function renderConfig(app) {
 21	  showLoading(app);
 22	
 23	  Promise.all([
 24	    API.getConfig(),
 25	    API.getModels ? API.getModels() : Promise.resolve([]),
 26	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
 27	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
 28	  ]).then(function (results) {
 29	    var config      = results[0];
 30	    var models      = results[1];
 31	    var personas    = results[2];
 32	    var assignments = results[3];
 33	
 34	    renderConfigPage(app, config, models, personas, assignments);
 35	  }).catch(function (err) {
 36	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
 37	  });
 38	}
 39	
 40	/* ── Page scaffold ───────────────────────────────────────── */
 41	
 42	function renderConfigPage(app, config, models, personas, assignments) {
 43	  /* Reset dirty flags — fresh server data has just been loaded, so any stale
 44	     dirty state from a previous page visit is no longer meaningful. */
 45	  configDirty.general       = false;
 46	  configDirty.personaModels = false;
 47	  configDirty.modelRegistry = false;
 48	
 49	  app.innerHTML =
 50	    '<div class="page-header"><h1>Configuration</h1></div>' +
 51	    '<div class="config-tabs" id="config-tab-bar">' +
 52	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
 53	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
 54	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
 55	    '</div>' +
 56	    '<div id="config-tab-content"></div>';
 57	
 58	  /* Render active tab content */
 59	  renderConfigTabContent(config, models, personas, assignments);
 60	
 61	  /* Wire tab-bar clicks */
 62	  var tabBar = document.getElementById('config-tab-bar');
 63	  if (tabBar) {
 64	    tabBar.addEventListener('click', function (e) {
 65	      var btn = e.target.closest('button[data-tab]');
 66	      if (!btn) return;
 67	      var tab = btn.getAttribute('data-tab');
 68	      if (tab === configActiveTab) return;
 69	
 70	      /* Unsaved-changes guard */
 71	      if (configDirty[configActiveTab]) {
 72	        if (!confirm('You have unsaved changes. Discard them?')) {
 73	          return; /* Stay */
 74	        }
 75	        configDirty[configActiveTab] = false;
 76	      }
 77	
 78	      /* Update active tab state */
 79	      configActiveTab = tab;
 80	
 81	      /* Update active class on buttons without re-rendering the full page */
 82	      var allBtns = tabBar.querySelectorAll('.config-tab');
 83	      allBtns.forEach(function (b) {
 84	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
 85	      });
 86	
 87	      /* Re-render only the tab content area */
 88	      renderConfigTabContent(config, models, personas, assignments);
 89	    });
 90	  }
 91	}
 92	
 93	/* ── Tab content dispatcher ──────────────────────────────── */
 94	
 95	function renderConfigTabContent(config, models, personas, assignments) {
 96	  var contentEl = document.getElementById('config-tab-content');
 97	  if (!contentEl) return;
 98	
 99	  if (configActiveTab === 'general') {
100	    contentEl.innerHTML = renderGeneralTab(config);

101	    wireGeneralTabEvents();
102	  } else if (configActiveTab === 'personaModels') {
103	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
104	  } else if (configActiveTab === 'modelRegistry') {
105	    contentEl.innerHTML = renderModelRegistryTab(models);
106	  }
107	}
108	
109	/* ── General tab ─────────────────────────────────────────── */
110	
111	function renderGeneralTab(config) {
112	  return UI.card(null,
113	    '<form id="config-form">' +
114	      '<div class="form-group">' +
115	        '<label class="form-label" for="auto-handoff">' +
116	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
117	          ' Auto-handoff enabled' +
118	        '</label>' +
119	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
120	      '</div>' +
121	      '<div class="form-group">' +
122	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
123	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
124	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
125	      '</div>' +
126	      '<div class="form-group">' +
127	        '<label class="form-label" for="capture-dialogues">' +
128	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
129	          ' Capture agent dialogues' +
130	        '</label>' +
131	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
132	      '</div>' +
133	      '<div class="form-group">' +
134	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
135	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
136	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
137	      '</div>' +
138	      '<div class="form-group">' +
139	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
140	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
141	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
142	      '</div>' +
143	      '<button type="submit" class="btn btn-primary">Save</button>' +
144	      '<div id="config-msg"></div>' +
145	    '</form>',
146	    { style: 'max-width:560px' }
147	  );
148	}
149	
150	function wireGeneralTabEvents() {
151	  var form = document.getElementById('config-form');
152	  if (!form) return;
153	
154	  /* Mark tab dirty on any input change.
155	     Both 'change' and 'input' are intentional: checkboxes fire 'change'
156	     (not 'input'), while text/number inputs fire 'input' on each keystroke.
157	     Using both ensures all form control types are covered. */
158	  form.addEventListener('change', function () {
159	    configDirty.general = true;
160	  });
161	  form.addEventListener('input', function () {
162	    configDirty.general = true;
163	  });
164	
165	  form.addEventListener('submit', function (e) {
166	    e.preventDefault();
167	    var autoHandoff = document.getElementById('auto-handoff').checked;
168	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
169	    if (isNaN(maxDepth) || maxDepth < 1) {
170	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
171	      return;
172	    }
173	    var captureDialogues = document.getElementById('capture-dialogues').checked;
174	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
175	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
176	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
177	      return;
178	    }
179	    /* ledger_root intentionally omitted (read-only) */
180	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
181	      .then(function () {
182	        configDirty.general = false;
183	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
184	      })
185	      .catch(function (err) {
186	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
187	      });
188	  });
189	}
190	
191	/* ── Persona Models tab (stub) ───────────────────────────── */
192	
193	function renderPersonaModelsTab(models, personas, assignments) {
194	  return UI.card(null,
195	    '<div class="empty-state">' +
196	      '<p class="empty-state-text">Persona Models — Coming soon</p>' +
197	      '<p class="form-note">Per-persona model assignment will be available in a future release.</p>' +
198	    '</div>',
199	    { style: 'max-width:560px' }
200	  );
201	}
202	
203	/* ── Model Registry tab (stub) ───────────────────────────── */
204	
205	function renderModelRegistryTab(models) {
206	  return UI.card(null,
207	    '<div class="empty-state">' +
208	      '<p class="empty-state-text">Model Registry — Coming soon</p>' +
209	      '<p class="form-note">The model registry for configuring available AI models will be available in a future release.</p>' +
210	    '</div>',
211	    { style: 'max-width:560px' }
212	  );
213	}

